$ErrorActionPreference = 'Stop'
$file = 'profisee_ConnectBaseline_PDATA_{{ProfiseeVersionCode}}.bak'
$c = New-Object System.Data.SqlClient.SqlConnection '{{$ref:connect/databases:MasterConnectionString}};Connect Timeout=30'
$c.Open()
try {
    $q = $c.CreateCommand()
    $q.CommandText = "DECLARE @dir nvarchar(400) = CAST(SERVERPROPERTY('InstanceDefaultBackupPath') AS nvarchar(400)); DECLARE @exists int, @f nvarchar(600) = @dir + N'\' + @file; EXEC master.dbo.xp_fileexist @f, @exists OUTPUT; SELECT @exists;"
    [void]$q.Parameters.AddWithValue('@file', $file)
    $exists = [int]$q.ExecuteScalar()
}
finally { $c.Close() }
if ($exists -eq 1) { 'false' } else { 'true' }

if ('{{BaseMissing}}' -eq 'true') {
    "No Connect baseline profisee_ConnectBaseline_PDATA_{{ProfiseeVersionCode}}.bak for version {{ProfiseeVersionCode}} on {{$ref:connect/machines:DatabaseServerName}} yet; it will be made."
} else {
    "Connect baseline profisee_ConnectBaseline_PDATA_{{ProfiseeVersionCode}}.bak for version {{ProfiseeVersionCode}} already exists; nothing done."
}
